// Krillion-style everyday and pop-culture prompts live in data-pop.js.
// pop: true puts them first in the queue, so races feel like Krillion before the trivia-heavy ones.
// Extra answers pulled from Wikidata (tools/build-answers.mjs) fill out CRUISING, FAST LANE and
// DEEP CUT so far more real answers count. The hand-written tiers come first and always win.
// data-more.js has extra hand-written answers for prompts Wikidata can't fill well.
// An extra answer that's already listed anywhere (any spelling) is skipped, so hand-written tiers win.
const withExtra = (q) => {
  const add = [MORE[q.q], EXTRA[q.q]].filter(Boolean);
  if (!add.length) return q;
  const seen = new Set(q.a.flat().flatMap((e) => e.split("|")).map(normalize));
  const a = q.a.map((list) => [...list]);
  for (let t = 1; t <= 3; t++) {
    for (const m of add) {
      for (const entry of m[t - 1] || []) {
        // "monza circuit" or "the nile river" is the hand-written answer with a category word on it: skip it,
        // or typing the long form would score as rarer than the hand-written tier
        const bare = (k) => {
          const w = k.split(" ");
          if (w.length > 2 && ["ice cream", "national park", "video game", "soft drink"].includes(w.slice(-2).join(" "))) return w.slice(0, -2).join(" ");
          return w.length > 1 && FILLER.has(w[w.length - 1]) ? w.slice(0, -1).join(" ") : k;
        };
        if (entry.split("|").some((f) => seen.has(bare(normalize(f))) && bare(normalize(f)) !== normalize(f))) continue;
        const forms = entry.split("|").filter((f) => { const k = normalize(f); if (!k || seen.has(k)) return false; seen.add(k); return true; });
        if (forms.length) a[t].push(forms.join("|"));
      }
    }
  }
  return { ...q, a };
};

// HAND_QUESTIONS: just the hand-written answers (the answer builder uses these).
export const HAND_QUESTIONS = [...CORE_QUESTIONS, ...[...POP_QUESTIONS, ...HAND2_QUESTIONS, ...HAND3_QUESTIONS].map((q) => ({ ...q, pop: true }))];
// Whole prompts generated from Wikidata (tools/prompt-sources.mjs), mixed in with the everyday ones.
const handNames = new Set(HAND_QUESTIONS.map((q) => q.q));
const GENERATED = Object.values(GEN).filter((q) => !handNames.has(q.q)).map(({ tiers, ...q }) => ({ ...q, pop: true }));
// each prompt carries its topic (cat) and whether it is niche (hard: HARD MODE only)
export const QUESTIONS = [...HAND_QUESTIONS.map(withExtra), ...GENERATED].map((q) => ({ ...q, ...classify(q) }));
